CREATE TABLE `ccms_purchase` (
  `CM_Product_ID` varchar(25) NOT NULL,
  `CM_Company_ID` varchar(25) DEFAULT NULL,
  `CM_Godown_ID` varchar(25) DEFAULT NULL,
  `CM_Bill_Number` varchar(50) DEFAULT NULL,
  `CM_Product_Name` varchar(255) DEFAULT NULL,
  `CM_Category_ID` varchar(25) DEFAULT NULL,
  `CM_Subcategory_ID` varchar(25) DEFAULT NULL,
  `CM_Supplier_ID` varchar(25) DEFAULT NULL,
  `CM_Item_ID` varchar(25) DEFAULT NULL,
  `CM_Unit_Price` decimal(15,2) DEFAULT NULL,
  `CM_Discount_Percentage` decimal(5,2) DEFAULT NULL,
  `CM_Discount_Amount` decimal(15,2) DEFAULT NULL,
  `CM_Net_Price` decimal(15,2) DEFAULT NULL,
  `CM_Quantity` decimal(15,2) DEFAULT NULL,
  `CM_Unit_Type` varchar(50) DEFAULT NULL,
  `CM_Total_Price` decimal(15,2) DEFAULT NULL,
  `CM_Payment_Terms` varchar(100) DEFAULT NULL,
  `CM_Purchase_Date` date DEFAULT NULL,
  `CM_Status` varchar(50) DEFAULT NULL,
  `CM_HSN_ASC_Code` varchar(50) DEFAULT NULL,
  `CM_Tax_Type` enum('GST','CGST/SGST','IGST') DEFAULT 'GST',
  `CM_Tax_Percentage` decimal(5,2) DEFAULT NULL,
  `CM_Tax_Amount` decimal(12,2) DEFAULT NULL,
  `CM_Grand_Total` decimal(15,2) DEFAULT NULL,
  `CM_Delivery_Location` varchar(100) DEFAULT NULL,
  `CM_Delivery_Date` datetime DEFAULT NULL,
  `CM_Payment_Status` enum('Paid','Partially Paid','Unpaid') DEFAULT NULL,
  `CM_Is_Status` enum('Active','Inactive') DEFAULT NULL,
  `CM_Image_URL` text,
  `CM_Advance_Payment` decimal(15,2) DEFAULT NULL,
  `CM_Balance_Payment` decimal(15,2) DEFAULT NULL,
  `CM_Round_off` decimal(10,2) DEFAULT NULL,
  `CM_Created_By` varchar(50) DEFAULT NULL,
  `CM_Created_At` datetime DEFAULT NULL,
  `CM_Uploaded_By` varchar(50) DEFAULT NULL,
  `CM_Uploaded_At` datetime DEFAULT NULL,
  PRIMARY KEY (`CM_Product_ID`),
  KEY `fk_purchase_company` (`CM_Company_ID`),
  KEY `fk_purchase_godown` (`CM_Godown_ID`),
  KEY `fk_purchase_category` (`CM_Category_ID`),
  KEY `fk_purchase_subcategory` (`CM_Subcategory_ID`),
  KEY `fk_purchase_supplier` (`CM_Supplier_ID`),
  KEY `fk_purchase_item` (`CM_Item_ID`),
  CONSTRAINT `fk_purchase_category` FOREIGN KEY (`CM_Category_ID`) REFERENCES `ccms_category` (`CM_Category_ID`),
  CONSTRAINT `fk_purchase_company` FOREIGN KEY (`CM_Company_ID`) REFERENCES `ccms_companies` (`CM_Company_ID`),
  CONSTRAINT `fk_purchase_godown` FOREIGN KEY (`CM_Godown_ID`) REFERENCES `ccms_godown` (`CM_Godown_ID`),
  CONSTRAINT `fk_purchase_item` FOREIGN KEY (`CM_Item_ID`) REFERENCES `ccms_item_master` (`CM_Item_ID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_purchase_subcategory` FOREIGN KEY (`CM_Subcategory_ID`) REFERENCES `ccms_subcategory` (`CM_Subcategory_ID`),
  CONSTRAINT `fk_purchase_supplier` FOREIGN KEY (`CM_Supplier_ID`) REFERENCES `ccms_suppliers` (`CM_Supplier_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
